{"code": "
fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"
VAL = {'p':100,'n':320,'b':330,'r':500,'q':900,'k':0}

def evaluate(pos):
    if pos.get('game_over'):
        w = pos.get('winner')
        r = pos.get('result')
        if w == 'white':
            return 100000
        if w == 'black':
            return -100000
        return 0
    board = pos['squares']
    score = 0
    # board may be dict or list of rows
    if isinstance(board, dict):
        items = board.items()
    else:
        items = []
        for r in board:
            if isinstance(r, dict):
                items.extend(r.items())
            else:
                items.extend(r)
    for sq, pc in items:
        if not pc or pc == '.':
            continue
        color = 'w' if pc.isupper() else 'b'
        low = pc.lower()
        v = VAL[low]
        s = v if color == 'w' else -v
        if sq in ('d4','e4','d5','e5'):
            s += 12 if color == 'w' else -12
        score += s
    turn = pos['turn']
    if pos.get('in_check') or pos.get('is_check'):
        score += 25 if turn == 'black' else -25
    return score

cur = simulate_move(fen, None)
print(cur['turn'], cur.get('game_over'))
cands = sorted(cur['legal_moves'])
results = []
for c in cands:
    aw = simulate_move(fen, c)
    replies = aw['legal_moves']
    if aw.get('game_over'):
        sc = evaluate(aw)
    else:
        sc = min(evaluate(simulate_move(aw['fen'], r)) for r in replies)
    results.append((sc, c))
    print(c, sc)

best = None
bestsc = None
for sc, c in results:
    if bestsc is None or sc > bestsc:
        bestsc = sc; best = c
print("BEST", best, bestsc)
play_move(best)
"}

